// 界面端到端冒烟验证：逐视图驱动真实界面，断言渲染结果，并捕获页面异常
// 用法：node scripts/ui-smoke.mjs   （应用需以 --remote-debugging-port=9333 运行）
import fs from "node:fs";
import WebSocket from "ws";

const PORT = process.env.CDP_PORT || "9333";
const SHOT_DIR = ".build";

async function connect() {
  const res = await fetch("http://127.0.0.1:" + PORT + "/json/list");
  const page = (await res.json()).find((t) => t.type === "page");
  if (!page) throw new Error("未找到页面目标");
  const ws = await new Promise((resolve, reject) => {
    const socket = new WebSocket(page.webSocketDebuggerUrl);
    socket.on("open", () => resolve(socket));
    socket.on("error", reject);
  });
  let id = 0;
  const pending = new Map();
  const errors = [];
  ws.on("message", (raw) => {
    const msg = JSON.parse(raw.toString());
    if (msg.id && pending.has(msg.id)) {
      const { resolve } = pending.get(msg.id);
      pending.delete(msg.id);
      resolve(msg.result);
      return;
    }
    if (msg.method === "Runtime.exceptionThrown") {
      const d = msg.params.exceptionDetails;
      errors.push("exception: " + (d.exception?.description || d.text));
    }
    if (msg.method === "Runtime.consoleAPICalled" && msg.params.type === "error") {
      errors.push("console.error: " + (msg.params.args || []).map((a) => a.value ?? a.description).join(" "));
    }
  });
  const send = (method, params = {}) => {
    const mid = ++id;
    ws.send(JSON.stringify({ id: mid, method, params }));
    return new Promise((resolve) => pending.set(mid, { resolve }));
  };
  await send("Runtime.enable");
  await send("Page.enable");
  return { ws, send, errors };
}

const { ws, send, errors } = await connect();
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function evaluate(expression) {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) return { __error: r.exceptionDetails.exception?.description || "eval error" };
  return r.result.value;
}
async function shot(name) {
  const s = await send("Page.captureScreenshot", { format: "png" });
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  fs.writeFileSync(SHOT_DIR + "/" + name, Buffer.from(s.data, "base64"));
}
async function click(js) {
  const r = await evaluate("(function(){" + js + "})()");
  await sleep(500);
  return r;
}
async function waitFor(jsExpr, timeout = 10000, interval = 300) {
  const deadline = Date.now() + timeout;
  while (Date.now() < deadline) {
    if (await evaluate(jsExpr)) return true;
    await sleep(interval);
  }
  return false;
}
async function typeInto(selector, text) {
  await waitFor("!!document.querySelector(" + JSON.stringify(selector) + ")", 8000);
  // 清空既有内容，避免上一轮遗留文本叠加
  await evaluate("(function(){var el=document.querySelector(" + JSON.stringify(selector) + ");el.focus();el.value='';el.dispatchEvent(new Event('input',{bubbles:true}));return el.value;})()");
  await sleep(250);
  for (const ch of text) {
    await send("Input.insertText", { text: ch });
    await sleep(35);
  }
  await sleep(300);
}

let pass = 0;
const fails = [];
function check(name, ok, detail) {
  if (ok) { pass++; console.log("  ok   " + name + (detail ? "  (" + detail + ")" : "")); }
  else { fails.push(name); console.log("  FAIL " + name + "  " + (detail || "")); }
}

console.log("=== 界面端到端冒烟验证 ===");

