// 0. 冷启动（队列为空）：播放按钮应能直接开始播放封面流选中的专辑
const cold = await evaluate("(async function(){var s=await window.__TAURI_INTERNALS__.invoke('player_state');return s.queue.length===0;})()");
if (cold) {
  await click("var b=document.querySelector('.ctrl-btn.play-btn');b&&b.click();return !!b;");
  await sleep(3500);
  const started = await evaluate("(async function(){var s=await window.__TAURI_INTERNALS__.invoke('player_state');return {status:s.status,queue:s.queue.length,title:s.current?s.current.title:null,album:s.current?s.current.album:null,pos:s.current?s.current.positionSecs:null};})()");
  check("播放按钮可直接开始播放（无需先选歌）", started.status === "playing" || started.status === "paused", "《" + started.title + "》(" + started.album + ") 队列 " + started.queue + " 首");
  await sleep(2500);
  const advanced = await evaluate("(async function(){var s=await window.__TAURI_INTERNALS__.invoke('player_state');return {pos:s.current?s.current.positionSecs:0,label:(document.querySelector('.time-label')||{}).textContent,wave:!!document.querySelector('.progress-slider canvas')};})()");
  check("播放进度真实推进", advanced.pos > 0.5, "位置 " + advanced.pos.toFixed(1) + "s · " + advanced.label + " · 波浪画布 " + advanced.wave);

  // 进度条拖拽跳转
  const box = await evaluate("(function(){var el=document.querySelector('.progress-slider');var r=el.getBoundingClientRect();return {x:r.left,y:r.top,w:r.width,h:r.height};})()");
  const targetX = Math.round(box.x + box.w * 0.75);
  const targetY = Math.round(box.y + box.h / 2);
  await send("Input.dispatchMouseEvent", { type: "mousePressed", x: targetX, y: targetY, button: "left", clickCount: 1 });
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: targetX, y: targetY, button: "left" });
  await send("Input.dispatchMouseEvent", { type: "mouseReleased", x: targetX, y: targetY, button: "left", clickCount: 1 });
  await sleep(1800);
  const seeked = await evaluate("(async function(){var s=await window.__TAURI_INTERNALS__.invoke('player_state');var d=s.current?s.current.durationSecs:0;return {pos:s.current?s.current.positionSecs:0,dur:d,label:(document.querySelector('.time-label')||{}).textContent};})()");
  check("进度条拖拽可跳转", seeked.dur > 0 && seeked.pos > seeked.dur * 0.6, "跳到 " + seeked.pos.toFixed(1) + "s / " + seeked.dur.toFixed(1) + "s · " + seeked.label);
} else {
  console.log("  -- 跳过冷启动检查（队列中已有曲目）");
}

// 1. 首页封面流
await click("var b=[].slice.call(document.querySelectorAll('.nav-item')).find(function(x){return x.textContent.indexOf('Home')>=0});b&&b.click();return !!b;");
await sleep(1200);
const home = await evaluate("(function(){return {cards:document.querySelectorAll('.cf-card').length,dots:document.querySelectorAll('.cf-dot').length,greet:(document.querySelector('.greeting-title')||{}).textContent,active:document.querySelectorAll('.cf-dot.active').length,meta:(document.querySelector('.cf-meta h3')||{}).textContent};})()");
check("首页封面流渲染", home.cards >= 3 && home.cards <= 5, "卡片 " + home.cards + " 张，圆点 " + home.dots + " 个，当前《" + home.meta + "》");
check("问候语显示", !!home.greet, home.greet);
const coverIntegrity = await evaluate("(function(){var img=document.querySelector('.cf-cover img');if(!img)return {none:true};var box=img.parentElement.getBoundingClientRect();var r=img.getBoundingClientRect();return {fit:getComputedStyle(img).objectFit,nat:img.naturalWidth+'x'+img.naturalHeight,rendered:Math.round(r.width)+'x'+Math.round(r.height),box:Math.round(box.width)+'x'+Math.round(box.height),dw:Math.round(box.width-r.width),dh:Math.round(box.height-r.height)};})()");
check("封面流封面完整（object-fit: contain 且铺满方形区域）", !coverIntegrity.none && coverIntegrity.fit === "contain" && Math.abs(coverIntegrity.dw) <= 1 && Math.abs(coverIntegrity.dh) <= 1, coverIntegrity.none ? "未找到封面" : coverIntegrity.fit + " · 原图 " + coverIntegrity.nat + " · 渲染 " + coverIntegrity.rendered + " · 容器 " + coverIntegrity.box);
const queueCoverImg = await evaluate("(function(){var img=document.querySelector('.queue-item-cover img');if(!img)return {none:true};return {fit:getComputedStyle(img).objectFit,w:Math.round(img.getBoundingClientRect().width),nat:img.naturalWidth};})()");
const cardPlay = await evaluate("(async function(){var s0=await window.__TAURI_INTERNALS__.invoke('player_state');var card=document.querySelector('.cf-card.cf-active');if(!card)return {skip:true};card.click();await new Promise(function(r){setTimeout(r,2500);});var s=await window.__TAURI_INTERNALS__.invoke('player_state');return {before:s0.current?s0.current.album:null,after:s.current?s.current.album:null,status:s.status,title:s.current?s.current.title:null};})()");
check("点击封面流中心卡片即播放该专辑", cardPlay.skip || cardPlay.status === "playing", cardPlay.skip ? "无卡片" : "正在播放《" + cardPlay.after + "》· " + cardPlay.title);
const cardClean = await evaluate("(function(){var card=document.querySelector('.cf-card.cf-active');if(!card)return {none:true};return {buttons:card.querySelectorAll('button').length,badges:card.querySelectorAll('.cf-badge').length,buttonsAll:document.querySelectorAll('.cf-card button').length,badgesAll:document.querySelectorAll('.cf-badge').length};})()");
check("卡片上没有任何按钮和年份角标", !cardClean.none && cardClean.buttonsAll === 0 && cardClean.badgesAll === 0, "按钮 " + cardClean.buttonsAll + " 个 · 年份角标 " + cardClean.badgesAll + " 个");
const follow = await evaluate("(async function(){var inv=window.__TAURI_INTERNALS__.invoke;var centered=(document.querySelector('.cf-card.cf-active .cf-meta h3')||{}).textContent||'';var page=await inv('tracks_list',{filter:{page:1,pageSize:2000}});var other=page.items.find(function(x){return x.album&&x.album!==centered;});if(!other)return {skip:true};await inv('player_play_track',{trackId:other.id,queueTrackIds:[other.id]});await new Promise(function(r){setTimeout(r,2000);});var nav=[].slice.call(document.querySelectorAll('.nav-item')).find(function(x){return x.textContent.indexOf('Home')>=0});if(nav)nav.click();await new Promise(function(r){setTimeout(r,2500);});var now=(document.querySelector('.cf-card.cf-active .cf-meta h3')||{}).textContent||'';var st=await inv('player_state');var albums=await inv('albums_list',{page:1,pageSize:1000});var alb=null;for(var ai=0;ai<albums.items.length;ai++){var it=albums.items[ai];if(st.current&&(it.id===st.current.trackId||(it.name===st.current.album&&it.artist===st.current.artist))){alb=it;break;}}var expect=alb?(alb.singleTitle&&alb.singleTitle.length?alb.singleTitle:alb.name):null;var h3=card?card.querySelector('.cf-meta h3'):null;var item=h3?h3.querySelector('[data-marquee-item]'):null;var shown=item?item.textContent:(h3?h3.textContent:null);return {centered:centered,album:other.album,now:shown,expect:expect,title:other.title,playing:st.current?st.current.album:null};})()");
check("封面流中心跟随正在播放的歌曲", follow.skip === true || (follow.expect !== null && follow.now === follow.expect), follow.skip ? "跳过（库内无其他专辑）" : "正在播放《" + follow.title + "》(" + follow.album + ") → 中心卡片《" + follow.now + "》（应为《" + follow.expect + "》）");
// 无名专辑（标签缺失）也要能跟随：播放一首专辑名为空的曲目
const nameless = await evaluate("(async function(){var inv=window.__TAURI_INTERNALS__.invoke;var p=await inv('tracks_list',{filter:{page:1,pageSize:2000}});var t=p.items.find(function(x){return !x.album||!x.album.trim();});if(!t)return {skip:true};await inv('player_play_track',{trackId:t.id,queueTrackIds:[t.id]});await new Promise(function(r){setTimeout(r,1500);});var nav=[].slice.call(document.querySelectorAll('.nav-item')).find(function(x){return x.textContent.indexOf('Home')>=0});if(nav)nav.click();await new Promise(function(r){setTimeout(r,2500);});var card=document.querySelector('.cf-card.cf-active');var img=card?card.querySelector('.cf-cover img'):null;var st=await inv('player_state');return {title:t.title,cardTitle:(card&&card.querySelector('.cf-meta h3')||{}).textContent,cardArtist:(card&&card.querySelector('.cf-meta p')||{}).textContent,cardOK:!!img&&img.naturalWidth>0,playing:st.current?st.current.title:null};})()");
check("专辑名为空的曲目：卡片显示曲目名并跟随播放", nameless.skip || (nameless.cardTitle === nameless.title && nameless.cardOK && nameless.playing === nameless.title), nameless.skip ? "库内无此类曲目" : "播放《" + nameless.title + "》→ 中心卡片《" + nameless.cardTitle + "》/" + nameless.cardArtist + "，封面已加载 " + nameless.cardOK);

// 拖动卡片 = 切换播放
const dragInfo = await evaluate("(async function(){var st=await window.__TAURI_INTERNALS__.invoke('player_state');var sec=document.querySelector('.coverflow-section');if(!sec)return {skip:true};var r=sec.getBoundingClientRect();return {y:Math.round(r.top+160),x1:Math.round(r.left+r.width/2+90),x2:Math.round(r.left+r.width/2-90),title:st.current?st.current.title:null};})()");
if (!dragInfo.skip) {
  await send("Input.dispatchMouseEvent", { type: "mousePressed", x: dragInfo.x1, y: dragInfo.y, button: "left", clickCount: 1 });
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: dragInfo.x1 - 55, y: dragInfo.y, button: "left" });
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: dragInfo.x2, y: dragInfo.y, button: "left" });
  await send("Input.dispatchMouseEvent", { type: "mouseReleased", x: dragInfo.x2, y: dragInfo.y, button: "left", clickCount: 1 });
  await sleep(2500);
  const after = await evaluate("(async function(){var s=await window.__TAURI_INTERNALS__.invoke('player_state');var card=document.querySelector('.cf-card.cf-active');return {title:s.current?s.current.title:null,card:(card&&card.querySelector('.cf-meta h3')||{}).textContent};})()");
  check("左右拖动卡片直接切换播放", after.title !== dragInfo.title, "拖动前《" + dragInfo.title + "》→ 拖动后《" + after.title + "》· 中心卡片《" + after.card + "》");
} else {
  check("左右拖动卡片直接切换播放", false, "未找到封面流");
}

// 超长专辑名循环滚动（跑马灯）
const marquee = await evaluate("(async function(){var inv=window.__TAURI_INTERNALS__.invoke;var page=await inv('albums_list',{page:1,pageSize:1000});var dispName=function(a){return (a.singleTitle&&a.singleTitle.length?a.singleTitle:a.name)||'';};var longest=page.items.slice().sort(function(a,b){return dispName(b).length-dispName(a).length;})[0];if(!longest)return {skip:true};var tracks=await inv('album_tracks',{albumId:longest.id});if(!tracks.length)return {skip:true};await inv('player_play_track',{trackId:tracks[0].id,queueTrackIds:[tracks[0].id]});await new Promise(function(r){setTimeout(r,1800);});var nav=[].slice.call(document.querySelectorAll('.nav-item')).find(function(x){return x.textContent.indexOf('Home')>=0});if(nav)nav.click();await new Promise(function(r){setTimeout(r,2600);});var h=document.querySelector('.cf-card.cf-active .cf-meta h3');var tr=h?h.querySelector('.marquee-track'):null;var short=document.querySelector('.cf-card .cf-meta h3:not(.marquee)');return {album:dispName(longest),len:dispName(longest).length,anim:tr?getComputedStyle(tr).animationName:null,dur:tr?getComputedStyle(tr).animationDuration:null,copies:h?h.querySelectorAll('[data-marquee-item]').length:0,shortPlain:!!short};})()");
check("超长专辑名循环滚动（跑马灯）", marquee.skip || (marquee.anim === "cf-marquee" && marquee.copies === 2 && marquee.shortPlain), marquee.skip ? "无专辑" : "《" + marquee.album.slice(0, 24) + "…》(" + marquee.len + " 字) 动画 " + marquee.anim + " " + marquee.dur + " · 副本 " + marquee.copies + " 份 · 短名不滚动 " + marquee.shortPlain);

// 回归：拖拽窗口边框会改变 canvas 尺寸，而给 canvas.width 赋值会**重置绘制缓冲**
// （上下文是 alpha:false → 重置后是不透明黑）。旧代码只改尺寸不补画，于是拖拽时背景
// 一闪一闪变黑、暂停时更是会一直黑下去。这里在暂停态（动画循环已停）改变画布尺寸，
// 数一次 drawArrays：修复后 applySize 会立刻补一帧（draws >= 1），旧代码为 0。
const ambGuard = await evaluate("(async function(){var sleep=function(ms){return new Promise(function(r){setTimeout(r,ms);});};var inv=window.__TAURI_INTERNALS__.invoke;var nav=[].slice.call(document.querySelectorAll('.nav-item')).find(function(x){return x.textContent.indexOf('Home')>=0;});if(nav){nav.click();}var c=null;for(var w=0;w<14&&!c;w++){await sleep(500);c=document.querySelector('.home-ambient canvas');}if(!c){var amb=document.querySelector('.home-ambient');return {skip:amb?(amb.classList.contains('fallback')?'氛围背景处于降级（WebGL 不可用）':'氛围容器在但没有画布'):'首页没有氛围容器'};}var gl=c.getContext('webgl2');if(!gl){return {skip:'WebGL 不可用'};}var st0=await inv('player_state');var wasPlaying=st0.status==='playing';if(wasPlaying){await inv('player_pause');await sleep(1000);}var draws=0,orig=gl.drawArrays;gl.drawArrays=function(){draws++;return orig.apply(gl,arguments);};var before=c.width;c.style.width='70%';c.style.height='70%';await sleep(900);var out={changed:c.width!==before,draws:draws,from:before,to:c.width};c.style.width='100%';c.style.height='100%';await sleep(900);gl.drawArrays=orig;if(wasPlaying){await inv('player_resume');}return out;})()");
check("氛围画布改尺寸后会立刻补画（背景不变黑）", !ambGuard.__error && (ambGuard.skip || (ambGuard.changed === true && ambGuard.draws >= 1)), ambGuard.__error ? "异常：" + ambGuard.__error : (ambGuard.skip ? "跳过（" + ambGuard.skip + "）" : "画布 " + ambGuard.from + " → " + ambGuard.to + " · 重建后补画 " + ambGuard.draws + " 帧（0 = 黑底）"));

// 回归：WebGL 上下文创建失败后**不能永久降级**。
// 旧实现一旦 setFallback(true)，canvas 的渲染条件 `!fallback && active` 就再也不满足，
// 而 effect 的依赖只有 [active] —— canvasRef.current 恒为 null，连重试机会都没有，
// 整个会话都不会恢复（实测只有刷新页面才回来）。这里注入一次创建失败验证能自愈。
const ambRecover = await evaluate("(async function(){var sleep=function(ms){return new Promise(function(r){setTimeout(r,ms);});};var navTo=function(n){var b=[].slice.call(document.querySelectorAll('.nav-item')).find(function(x){return x.textContent.indexOf(n)>=0;});if(b)b.click();};if(!document.querySelector('.home-ambient'))return {skip:'没有氛围背景'};var orig=HTMLCanvasElement.prototype.getContext,remain=1;HTMLCanvasElement.prototype.getContext=function(t){if(t==='webgl2'&&remain>0){remain--;return null;}return orig.apply(this,arguments);};navTo('Library');await sleep(900);navTo('Home');await sleep(1400);var a=document.querySelector('.home-ambient');var degraded=!!(a&&a.classList.contains('fallback'));var recover=null;for(var i=0;i<16;i++){await sleep(500);if(document.querySelectorAll('.home-ambient canvas').length>0){recover=((i+1)*0.5).toFixed(1)+'s';break;}}var a2=document.querySelector('.home-ambient');HTMLCanvasElement.prototype.getContext=orig;return {degraded:degraded,recover:recover,restored:!a2||!a2.classList.contains('fallback'),canvas:document.querySelectorAll('.home-ambient canvas').length};})()");
check("氛围背景在 WebGL 创建失败后能自愈", !ambRecover.__error && (ambRecover.skip || (ambRecover.degraded === true && ambRecover.restored === true && ambRecover.canvas === 1)), ambRecover.__error ? "异常：" + ambRecover.__error : (ambRecover.skip ? "跳过（" + ambRecover.skip + "）" : "注入失败后降级=" + ambRecover.degraded + " · " + ambRecover.recover + " 后自愈=" + ambRecover.restored + "（画布 " + ambRecover.canvas + " 块）"));

// 大窗口 / 全屏下自动放大
await send("Emulation.setDeviceMetricsOverride", { width: 1920, height: 1080, deviceScaleFactor: 1, mobile: false });
await sleep(1200);
const big = await evaluate("(function(){var p=document.querySelector('.cf-perspective');var c=document.querySelector('.cf-card.cf-active');return {persp:Math.round(p.getBoundingClientRect().width),card:Math.round(c.getBoundingClientRect().width)};})()");
check("全屏/大窗口下卡片自动放大", big.card > 300 && big.persp > 925, "1920×1080 下卡片宽 " + big.card + "px（最小窗口 260px）· 舞台 " + big.persp + "px");

// 最小窗口：舞台窄于设计基准 920 → stageScale 的 Math.max(1, …) 把它钳在 1，卡片就是设计稿尺寸
