const small = await evaluate("(function(){return Math.round(document.querySelector('.cf-card.cf-active').getBoundingClientRect().width);})()");
check("最小窗口下保持设计稿尺寸", Math.abs(small - 260) <= 4, "卡片宽 " + small + "px（设计稿 224×1.095×透视放大1.061≈260px；舞台窄于 920 基准 → 缩放系数钳在 1）");

// 默认窗口（1267×902）比设计基准宽，封面流按「窗口变大就整体放大」的设计意图略微放大
