const pswitch = await evaluate("(async function(){var sleep=function(ms){return new Promise(function(r){setTimeout(r,ms);});};var inv=window.__TAURI_INTERNALS__.invoke;var rows=[].slice.call(document.querySelectorAll('.settings-row'));var row=null;for(var i=0;i<rows.length;i++){var lab=rows[i].querySelector('.settings-label');if(lab&&lab.textContent.indexOf(\"上一首回到本曲开头\")>=0){row=rows[i];break;}}if(!row){return {skip:\"设置页没有该开关\"};}if(!row.querySelector('.switch')){return {skip:\"该行没有 switch\"};}var before=await inv(\"settings_get\",{key:\"previousRestart\"});var wasOn=row.querySelector('.switch').classList.contains('on');row.querySelector('.switch').click();await sleep(800);var after=await inv(\"settings_get\",{key:\"previousRestart\"});var nowOn=row.querySelector('.switch').classList.contains('on');row.querySelector('.switch').click();await sleep(800);if(before===null){await inv(\"settings_delete\",{key:\"previousRestart\"});}var restored=await inv(\"settings_get\",{key:\"previousRestart\"});return {before:before,after:after,wasOn:wasOn,nowOn:nowOn,restored:restored,flipped:wasOn!==nowOn&&((after===\"on\")!==(before===\"on\"))&&restored===before};})()");
check("上一首行为开关可切换、落库并还原", !pswitch.__error && (pswitch.skip || pswitch.flipped === true), pswitch.__error ? "异常：" + pswitch.__error : (pswitch.skip ? "跳过（" + pswitch.skip + "）" : "初始 " + JSON.stringify(pswitch.before) + " → " + JSON.stringify(pswitch.after) + "（on=" + pswitch.wasOn + "→" + pswitch.nowOn + "）→ 还原 " + JSON.stringify(pswitch.restored)));
const strips = await evaluate("(function(){var list=[].slice.call(document.querySelectorAll('.folder-strip'));return {count:list.length,heights:list.map(function(el){return Math.round(el.getBoundingClientRect().height);}),paths:list.map(function(el){var s=el.querySelector('.folder-strip-path');return s?s.textContent:'';}),oneLine:list.every(function(el){var s=el.querySelector('.folder-strip-path');return !s||s.scrollHeight<=s.clientHeight+1;})};})()");
check("音乐文件夹为长条列表", strips.count > 0 && strips.heights.every(function(h){return h<=64;}) && strips.oneLine, strips.count + " 个文件夹 · 行高 " + strips.heights.join("/") + " · 单行显示 " + strips.oneLine + " · " + (strips.paths[0]||""));
